Unit Test Code:
#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_remove_digits_single_node(void) {
    // Setup: create a big_int list with exactly one node (no next_digit)
    // Use add_digit(NULL, value) to create a single node list
    big_int *single_node = add_digit(NULL, 5);
    TEST_ASSERT_NOT_NULL(single_node);
    TEST_ASSERT_NULL(single_node->next_digit);

    // Test: call remove_digits with N <= 0 to trigger the target path
    // Conditions: digit != NULL, digit->next_digit == NULL
    // This will execute: free(digit); digit = NULL; return 0;
    char result = remove_digits(single_node, 0);

    // Assertions
    TEST_ASSERT_EQUAL_INT(0, result);
    // The node has been freed, but the local pointer is not modified by the function
    // (parameter is passed by value, so digit = NULL inside function doesn't affect caller)
    // No further assertions on the freed pointer are safe.

    // Cleanup: The node was freed inside remove_digits, so we should not free again.
    // However, to be safe and avoid double-free, we set pointer to NULL.
    single_node = NULL;
}


